function shapes(l) {
  const names = {
    ko: { box: "상자", pallet: "팔레트", part: "부품", carton: "박스", bottle: "병", car: "승용차", truck: "트럭", bus: "버스", person: "사람", patient: "환자", bag: "가방", dot: "점" },
    en: { box: "Box", pallet: "Pallet", part: "Part", carton: "Carton", bottle: "Bottle", car: "Car", truck: "Truck", bus: "Bus", person: "Person", patient: "Patient", bag: "Bag", dot: "Dot" },
  }[l];
  const out = {};
  for (const [k, v] of Object.entries(names)) { out[`opt.shape.${k}`] = v; out[`opt.setShape.${k}`] = v; }
  return out;
}
